struct Node;

fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~') {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0F) as usize] as char);
        }
    }
    out
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;

        // Enrichment fetch (granted by the graph author). The result is
        // intentionally not used, so the node's output is unchanged; transport
        // failures are returned as values by `fetch` and ignored.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&q.question)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let knowledge = crate::aap::caps::kb_read::lookup(&q.question);

        ConversationContext {
            intent: q.intent,
            question: q.question,
            knowledge,
        }
    }
}

export!(Node);
